const mediaURLs=new Map();
async function cacheAttachment(key){if(!key||mediaURLs.has(key))return;try{const file=await readMedia(key);if(file){mediaURLs.set(key,URL.createObjectURL(file));render();}}catch{}}
function resolveMedia(key,fallback=''){if(!key)return fallback;const cached=mediaURLs.get(key);if(!cached)cacheAttachment(key);return cached||''}

