function credentialStore(){try{return JSON.parse(localStorage.getItem(USER_INDEX)||'{}')}catch{return {}}}
async function hashPassword(password,salt){const bytes=new TextEncoder().encode(password);const key=await crypto.subtle.importKey('raw',bytes,{name:'PBKDF2'},false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(salt),iterations:120000,hash:'SHA-256'},key,256);return Array.from(new Uint8Array(bits),b=>b.toString(16).padStart(2,'0')).join('')}
