function icon(name,size=20,cls='') { return `<svg class="icon ${cls}" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.info}</svg>`; }
function avatar(name, color, ink, url, size='md') {
  if (url) return `<span class="avatar avatar-${size}"><img alt="" src="${h(url)}"></span>`;
  const initials=String(name||'?').trim().split(/\s+/).slice(0,2).map(n=>n[0]).join('').toUpperCase();
  return `<span class="avatar avatar-${size}" style="--avatar:${color||'#d8e8f2'};--avatar-ink:${ink||'#11577f'}" aria-hidden="true">${h(initials)}</span>`;
}
function initials(name) {return (name||'').split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();}
function authorOf(post) { if(post.authorId===meId) return {...db.me,id:'me',name:db.me.name,color:'#d7eafa',ink:'#07577d'}; return PEERS.find(p=>p.id===post.authorId)||{name:'Anggota GrowMate',username:'@growmate',program:'Komunitas',id:'unknown'}; }
function prettyDate(iso) { try {return new Intl.DateTimeFormat('id-ID',{day:'numeric',month:'short',year:'numeric'}).format(new Date(iso));}catch{return 'Baru saja';} }
function todayString() {return new Intl.DateTimeFormat('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date());}
function firstName() {return db?.me?.name?.trim().split(' ')[0]||'Teman';}
function isOwn(post){return post.authorId===meId;}
function plural(n,singular,pluralValue) {return `${n} ${n===1?singular:pluralValue||singular}`;}
function categoryOptions(selected='all', includesAll=true) {return (includesAll?['all',...CATEGORIES]:CATEGORIES).map(c=>`<option value="${h(c)}" ${selected===c?'selected':''}>${c==='all'?'Semua mata kuliah':h(c)}</option>`).join('');}
function toast(message) {ui.toast=message; document.querySelector('#toast')?.remove(); const node=document.createElement('div'); node.id='toast'; node.className='toast'; node.setAttribute('role','status'); node.textContent=message;document.body.appendChild(node);clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.remove(),3600);}
function persist() {if(!saveAccount(db)) toast('Penyimpanan browser penuh atau diblokir. Perubahan ini mungkin tidak tersimpan.');}
function navButton(page, label, symbol) {return `<button class="nav-link ${ui.page===page?'active':''}" data-page="${page}" aria-current="${ui.page===page?'page':'false'}">${icon(symbol,20)}<span>${label}</span></button>`;}
function navigate(page){ui.page=page;ui.studyId=null;ui.category='all';ui.search='';ui.modal=null;ui.menu=false;document.body.classList.remove('modal-open');location.hash=page;render();window.scrollTo({top:0,behavior:'instant'});}

